    logic d;
    logic ena;
    logic q;

    TopModule dut (
        .d(d),
        .ena(ena),
        .q(q)
    );

    initial begin
        d = 0;
        ena = 0;
        #10;
        // With ena = 0, q should remain 0 (or undefined initially, but let's initialize d=0, ena=1 first to set it).

        ena = 1;
        d = 1;
        #10;
        if (q !== 1) begin
            $display("SELFTEST FAIL: expected q=1 when ena=1, d=1. Got q=%b", q);
            $finish;
        end

        // Now lower ena, change d, q should hold
        ena = 0;
        d = 0;
        #10;
        if (q !== 1) begin
            $display("SELFTEST FAIL: expected q to hold 1 when ena=0, got q=%b", q);
            $finish;
        end

        // Raise ena, d=0, q should become 0
        ena = 1;
        #10;
        if (q !== 0) begin
            $display("SELFTEST FAIL: expected q=0 when ena=1, d=0. Got q=%b", q);
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
